def minimal(routes, services='', extra=''):
 return 'var builder = WebApplication.CreateBuilder(args);\n'+services+'\nvar app = builder.Build();\n'+routes+'\napp.Run();\n'+extra+'\n'
def controller(methods, extra=''):
 return 'using Microsoft.AspNetCore.Mvc;\nusing System.ComponentModel.DataAnnotations;\nvar builder = WebApplication.CreateBuilder(args);\nbuilder.Services.AddControllers();\nvar app = builder.Build();\napp.MapControllers();\napp.Run();\n[ApiController]\n[Route("")]\npublic class LessonController : ControllerBase {\n'+methods+'\n}\n'+extra+'\n'
course('aspnet-core','ASP.NET Core','csharp','Examples use .NET 8 or later with minimal APIs.','Install the .NET SDK. Run dotnet new web -n School, enter School, and replace Program.cs with one example. Run dotnet run --urls http://127.0.0.1:8000. Stop the app before changing examples.','ASP.NET Core is a .NET tool for websites and APIs. Minimal APIs let a small function handle a web request.',[
L('first-route','Make a minimal route','MapGet connects a GET path to a function. Open GET /.',minimal('app.MapGet("/", () => "Hello, Asha!");'),'Hello, Asha!','Change the greeting.','MapGet only handles matching GET requests.'),
L('json','Return a data object','Results.Json sends structured data as JSON. Open GET /book.',minimal('app.MapGet("/book", () => Results.Json(new { title = "Moon Trip", pages = 24 }));'),'{"title":"Moon Trip","pages":24}','Add an author field.','Use objects for data instead of joining JSON text by hand.'),
L('path-values','Read a path input','Curly braces name a route value. Open GET /hello/Ravi.',minimal('app.MapGet("/hello/{name}", (string name) => $"Hi, {name}!");'),'Hi, Ravi!','Visit /hello/Asha.','Do not place user text into raw HTML without escaping it.'),
L('typed-paths','Constrain a route number','The int route constraint only matches whole numbers. Open GET /double/4.',minimal('app.MapGet("/double/{n:int}", (int n) => Results.Json(new { answer = n * 2 }));'),'{"answer":8}','Try /double/cat.','A failed route constraint usually means this route does not match.'),
L('query-values','Read an optional query','A simple input outside the path can come from the query string. GET /page with no n uses the fallback.',minimal('app.MapGet("/page", (int? n) => Results.Json(new { page = n ?? 1 }));'),'{"page":1}','Visit /page?n=3.','A missing optional number is null, not automatically zero.'),
L('post-body','Read a JSON record','A record can describe body data. Send POST /books with application/json and {"title":"Moon Trip"}.',minimal('app.MapPost("/books", (Book book) => Results.Json(book, statusCode: 201));','', 'record Book(string Title);'),'{"title":"Moon Trip"}','Send another title.','A type describes shape; add checks for values that must not be empty.'),
L('validation','Check a body value','The handler checks a title before returning a created response. Send POST /books with {"title":"Moon Trip"}.',minimal('app.MapPost("/books", (Book book) => {\n if (string.IsNullOrWhiteSpace(book.Title)) return Results.BadRequest(new { error = "Title needed" });\n return Results.Created("/books/1", book);\n});','', 'record Book(string? Title);'),'{"title":"Moon Trip"}','Send an empty title and inspect status 400.','Minimal APIs in this version do not make every custom validation rule for you.'),
L('middleware','Add a shared response rule','Middleware can run before and after later handlers. GET /note carries the header set here.',minimal('app.Use(async (context, next) => { context.Response.Headers["Cache-Control"] = "no-store"; await next(); });\napp.MapGet("/note", () => "Practice note");'),'Practice note','Inspect Cache-Control with curl -i.','Call next when the request should continue through the pipeline.'),
L('route-groups','Group related paths','MapGroup gives several routes one common prefix. Open GET /api/books.',minimal('var api = app.MapGroup("/api");\napi.MapGet("/books", () => new[] { "Moon Trip" });'),'["Moon Trip"]','Add a /pets route to the group.','The group prefix is part of each final route.'),
L('services','Receive a shared helper','A registered service can be an input to a handler. Open GET /school.',minimal('app.MapGet("/school", (SchoolName school) => school.Value);','builder.Services.AddSingleton(new SchoolName("Oak School"));','record SchoolName(string Value);'),'Oak School','Change the registered school name.','Register services before building the app.'),
L('not-found','Return a missing-item reply','Results.NotFound gives a 404 response. Open GET /missing.',minimal('app.MapGet("/missing", () => Results.NotFound(new { error = "Book not found" }));'),'{"error":"Book not found"}','Inspect the 404 status.','Use the error status as well as a helpful message.'),
L('redirects','Point a client elsewhere','Results.Redirect sends a location. A browser following GET /start reaches /hello.',minimal('app.MapGet("/start", () => Results.Redirect("/hello"));\napp.MapGet("/hello", () => "Welcome");'),'Welcome','Inspect the initial Location header.','A redirect asks the client to make a second request.')])
course('aspnet-web-api','ASP.NET Web API','csharp','These lessons use modern ASP.NET Core controller APIs on .NET 8 or later, not the older System.Web API.','Install the .NET SDK. Run dotnet new web -n SchoolApi and enter it. Replace Program.cs with one example. Run dotnet run --urls http://127.0.0.1:8000. These examples use controllers without a database.','A Web API sends data to other programs. ASP.NET Core controllers group the request actions into C# classes.',[
L('controllers','Make a controller action','A controller action handles a route. HttpGet maps GET /hello to the method.',controller('[HttpGet("hello")] public string Hello() => "Hello, Asha!";'),'Hello, Asha!','Change the greeting.','AddControllers and MapControllers are both needed.'),
L('json-results','Return a JSON object','Ok creates a successful response with data. Open GET /book.',controller('[HttpGet("book")] public IActionResult Book() => Ok(new { title = "Moon Trip", pages = 24 });'),'{"title":"Moon Trip","pages":24}','Add an author field.','Return data objects so the framework serialises them.'),
L('route-binding','Bind a route number','FromRoute reads a path value. Open GET /double/4.',controller('[HttpGet("double/{n:int}")] public IActionResult Twice([FromRoute] int n) => Ok(new { answer = n * 2 });'),'{"answer":8}','Try /double/cat.','A route constraint controls matching; it is not a full data validation policy.'),
L('query-binding','Read a query input','FromQuery makes the source of an input clear. GET /page with no n uses 1.',controller('[HttpGet("page")] public IActionResult Page([FromQuery] int n = 1) => Ok(new { page = n });'),'{"page":1}','Visit /page?n=3.','Inputs from clients still need suitable limits.'),
L('body-binding','Read a typed body','FromBody reads a JSON request body. Send POST /books with application/json and {"title":"Moon Trip"}.',controller('[HttpPost("books")] public IActionResult Create([FromBody] BookInput book) => Ok(book);','public record BookInput(string Title);'),'{"title":"Moon Trip"}','Post a different title.','Send the correct Content-Type so JSON can be parsed.'),
L('validation','Use a required field rule','ApiController checks validation attributes. A valid POST /books with {"title":"Moon Trip"} reaches this action.',controller('[HttpPost("books")] public IActionResult Create([FromBody] BookInput book) => Ok(book);','public class BookInput { [Required] public string? Title { get; set; } }'),'{"title":"Moon Trip"}','Post {} and inspect the automatic 400 response.','Required checks presence; add more rules for your actual needs.'),
L('created-results','Return a new item location','CreatedAtAction sends status 201 and a link to the new item. Send POST /books with {"title":"Moon Trip"}.',controller('[HttpGet("books/{id:int}")] public IActionResult ById(int id) => Ok(new { id });\n[HttpPost("books")] public IActionResult Create(BookInput book) => CreatedAtAction(nameof(ById), new { id = 1 }, book);','public record BookInput(string Title);'),'{"title":"Moon Trip"}','Inspect the Location header.','The named action and route values must identify a real route.'),
L('not-found','Report a missing book','NotFound creates a 404 result. Open GET /missing.',controller('[HttpGet("missing")] public IActionResult Missing() => NotFound(new { error = "Book not found" });'),'{"error":"Book not found"}','Inspect the status too.','A missing item should not look like a successful response.'),
L('lists','Return a typed collection','A collection becomes a JSON array. Open GET /books.',controller('[HttpGet("books")] public ActionResult<string[]> Books() => new[] { "Moon Trip", "Sun Trip" };'),'["Moon Trip","Sun Trip"]','Add a third book title.','Use a clear item shape for larger collections.'),
L('headers','Set a controller response header','A controller can set response metadata before returning a result. Open GET /note.',controller('[HttpGet("note")] public IActionResult Note() { Response.Headers["Cache-Control"] = "no-store"; return Ok(new { note = "Practice" }); }'),'{"note":"Practice"}','Inspect the Cache-Control header.','Headers must be set before the response starts.'),
L('no-content','Reply without a body','NoContent returns status 204. Send DELETE /books/1 for this practice response.',controller('[HttpDelete("books/{id:int}")] public IActionResult Remove(int id) => NoContent();'),'204 No Content; empty body','Inspect status and body with an HTTP client.','This sample only shows the response; it has no stored book to delete.'),
L('action-results','Choose between result kinds','IActionResult allows different outcomes. GET /score/8 returns a success; a negative score returns 400.',controller('[HttpGet("score/{n:int}")] public IActionResult Score(int n) { if (n < 0) return BadRequest(new { error = "Use zero or more" }); return Ok(new { score = n }); }'),'{"score":8}','Visit /score/-1.','Check invalid input before returning a success result.')])
